from typing import List
from collections import deque
class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        graph = [[] for _ in range(numCourses)]
        indegree = [0] * numCourses
        for course, prereq in prerequisites:
            graph[prereq].append(course)
            indegree[course] += 1
        queue = deque(i for i, degree in enumerate(indegree) if degree == 0)
        completed = 0
        while queue:
            node = queue.popleft()
            completed += 1
            for nxt in graph[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    queue.append(nxt)
        return completed == numCourses

import java.util.*;
class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
        int[] indegree = new int[numCourses];
        for (int[] edge : prerequisites) { graph.get(edge[1]).add(edge[0]); indegree[edge[0]]++; }
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) if (indegree[i] == 0) queue.add(i);
        int completed = 0;
        while (!queue.isEmpty()) {
            int node = queue.remove(); completed++;
            for (int next : graph.get(node)) if (--indegree[next] == 0) queue.add(next);
        }
        return completed == numCourses;
    }
}

class Trie:
    def __init__(self):
        self.children = {}
        self.terminal = False
    def insert(self, word: str) -> None:
        node = self
        for char in word:
            if char not in node.children:
                node.children[char] = Trie()
            node = node.children[char]
        node.terminal = True
    def search(self, word: str) -> bool:
        node = self
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.terminal
    def startsWith(self, prefix: str) -> bool:
        node = self
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

class Trie {
    private static class Node { Node[] children = new Node[26]; boolean terminal; }
    private final Node root = new Node();
    public Trie() {}
    public void insert(String word) {
        Node node = root;
        for (char ch : word.toCharArray()) {
            int i = ch - 'a'; if (node.children[i] == null) node.children[i] = new Node(); node = node.children[i];
        }
        node.terminal = true;
    }
    public boolean search(String word) { Node node = walk(word); return node != null && node.terminal; }
    public boolean startsWith(String prefix) { return walk(prefix) != null; }
    private Node walk(String text) {
        Node node = root;
        for (char ch : text.toCharArray()) { node = node.children[ch - 'a']; if (node == null) return null; }
        return node;
    }
}

