class Solution:
    def minSubArrayLen(self, target: int, nums: List[int]) -> int:
        left = total = 0
        best = len(nums) + 1
        for right, value in enumerate(nums):
            total += value
            while total >= target:
                best = min(best, right - left + 1)
                total -= nums[left]
                left += 1
        return 0 if best == len(nums) + 1 else best

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int left = 0, best = nums.length + 1; long sum = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (sum >= target) { best = Math.min(best, right - left + 1); sum -= nums[left++]; }
        }
        return best == nums.length + 1 ? 0 : best;
    }
}

class WordDictionary:
    def __init__(self):
        self.root = {}
    def addWord(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node['#'] = True
    def search(self, word: str) -> bool:
        def visit(node, index):
            if index == len(word):
                return '#' in node
            ch = word[index]
            if ch == '.':
                return any(visit(child, index + 1) for key, child in node.items() if key != '#')
            return ch in node and visit(node[ch], index + 1)
        return visit(self.root, 0)

import java.util.*;
class WordDictionary {
    private static class Node { Node[] children = new Node[26]; boolean terminal; }
    private final Node root = new Node();
    public WordDictionary() {}
    public void addWord(String word) { Node node = root; for (char ch : word.toCharArray()) { int i = ch - 'a'; if (node.children[i] == null) node.children[i] = new Node(); node = node.children[i]; } node.terminal = true; }
    public boolean search(String word) { return dfs(root, word, 0); }
    private boolean dfs(Node node, String word, int index) {
        if (index == word.length()) return node.terminal;
        char ch = word.charAt(index);
        if (ch == '.') { for (Node child : node.children) if (child != null && dfs(child, word, index + 1)) return true; return false; }
        Node child = node.children[ch - 'a']; return child != null && dfs(child, word, index + 1);
    }
}

from typing import List
class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        def linear(values):
            prev2 = prev1 = 0
            for value in values:
                prev2, prev1 = prev1, max(prev1, prev2 + value)
            return prev1
        return max(linear(nums[:-1]), linear(nums[1:]))

class Solution {
    public int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        return Math.max(linear(nums, 0, nums.length - 1), linear(nums, 1, nums.length));
    }
    private int linear(int[] nums, int start, int end) {
        int prev2 = 0, prev1 = 0;
        for (int i = start; i < end; i++) { int best = Math.max(prev1, prev2 + nums[i]); prev2 = prev1; prev1 = best; }
        return prev1;
    }
}

